<script setup lang="ts">
/**
 * CommentThread.Comment: one comment: its author, time, body, labels, actions and replies.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, inject, useId } from 'vue'

import styles from '@polymorph/recipes/structure/comment-thread.module.css'

export interface CommentThreadCommentProps {
  /**
   * The author's name, drawn first. With the time it names the comment's article.
   */
  author: string
  /**
   * The comment was changed after it was posted: the head says so after the time.
   */
  edited?: boolean
}

defineOptions({ name: 'CommentThreadComment', inheritAttrs: false })

withDefaults(defineProps<CommentThreadCommentProps>(), { edited: false })
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  avatar?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
  meta?: (props: Record<string, never>) => unknown
  replies?: (props: Record<string, never>) => unknown
  time?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const owner = inject<Record<string, any>>('polymorph:CommentThread', {})
const words = computed(() => owner.messages ?? { edited: 'Edited', replies: 'Replies' })
const authorId = computed(() => `${uid}-author`)
const timeId = computed(() => `${uid}-time`)
</script>

<template>
  <li :class="styles.comment">
    <article
      :class="styles.entry"
      :aria-labelledby="$slots.time ? `${authorId} ${timeId}` : authorId"
    >
      <span v-if="$slots.avatar" :class="styles.mark">
        <slot name="avatar" />
      </span>
      <div :class="styles.body">
        <div :class="styles.head">
          <span :class="styles.author" :id="authorId">
            {{ author }}
          </span>
          <span v-if="$slots.time" :class="styles.time" :id="timeId">
            <slot name="time" />
          </span>
          <span v-if="edited" :class="styles.edited">
            {{ words.edited }}
          </span>
          <span v-if="$slots.meta" :class="styles.meta">
            <slot name="meta" />
          </span>
        </div>
        <div :class="styles.content">
          <slot />
        </div>
        <div v-if="$slots.actions" :class="styles.actions">
          <slot name="actions" />
        </div>
      </div>
    </article>
    <ol v-if="$slots.replies" :class="styles.replies" role="list" :aria-label="words.replies">
      <slot name="replies" />
    </ol>
  </li>
</template>
